<?php
declare(strict_types=1);
function recordLinkedInPublishingAttempt(int $channelId,string $text,string $visibility,string $status,?string $postId,?string $errorCode):void{db()->prepare("INSERT INTO publishing_attempts(provider_id,social_channel_id,mode,final_text,visibility,external_post_id,status,error_code,created_at) VALUES('linkedin',?,'live',?,?,?,?,?,?)")->execute([$channelId,$text,$visibility,$postId,$status,$errorCode,date('Y-m-d H:i:s')]);}
function linkedInPostRequest(string $accessToken,array $payload):string{$headers=['Accept: application/json','Content-Type: application/json','Authorization: Bearer '.$accessToken,'X-Restli-Protocol-Version: 2.0.0','Linkedin-Version: '.LINKEDIN_API_VERSION];$body=@file_get_contents(rtrim(linkedInEndpoint('api'),'/').'/rest/posts',false,stream_context_create(['http'=>['method'=>'POST','timeout'=>10,'ignore_errors'=>true,'header'=>implode("\r\n",$headers),'content'=>json_encode($payload,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]]));$responseHeaders=$http_response_header??[];$status=0;if(isset($responseHeaders[0])&&preg_match('#\s(\d{3})\s#',$responseHeaders[0],$match))$status=(int)$match[1];$postId=null;foreach($responseHeaders as $header)if(stripos($header,'x-restli-id:')===0){$postId=trim(substr($header,strlen('x-restli-id:')));break;}if($status===201&&is_string($postId)&&$postId!==''&&strlen($postId)<=500)return $postId;if($status===401)throw new OAuthException('LINKEDIN_POST_TOKEN','Die LinkedIn-Verbindung ist abgelaufen. Bitte erneut verbinden.',422);if($status===403)throw new OAuthException('LINKEDIN_POST_FORBIDDEN','LinkedIn erlaubt die Veröffentlichung für dieses Profil nicht.',422);if($status===429)throw new OAuthException('LINKEDIN_POST_RATE_LIMIT','LinkedIn erlaubt derzeit keine weitere Veröffentlichung. Bitte später erneut versuchen.',429);if($status===400||$status===422)throw new OAuthException('LINKEDIN_POST_VALIDATION','LinkedIn hat den Beitrag wegen ungültiger Daten abgelehnt.',422);throw new OAuthException('LINKEDIN_POST_FAILED','LinkedIn konnte den Beitrag nicht veröffentlichen.',502);}
function publishLinkedInTestPost():never{requireAdmin();requireCsrf();$data=input();$channelId=$data['channelId']??null;$confirmed=$data['confirmed']??null;if(!is_int($channelId)||$channelId<1)fail('INVALID_INPUT','Ein gültiger LinkedIn-Zielkanal ist erforderlich.',422);if($confirmed!==true)fail('LINKEDIN_CONFIRMATION_REQUIRED','Die ausdrückliche Veröffentlichungsbestätigung fehlt.',422);$text=requireStringField($data,'text',3000);$visibility=requireStringField($data,'visibility',20);if($text==='')fail('INVALID_INPUT','Der Beitragstext darf nicht leer sein.',422);if(!in_array($visibility,['PUBLIC','CONNECTIONS'],true))fail('INVALID_INPUT','Ungültige LinkedIn-Sichtbarkeit.',422);$stmt=db()->prepare("SELECT c.id,c.channel_type,c.status,c.can_publish,a.external_account_id,a.access_token_encrypted,a.token_expires_at,a.scopes,a.status account_status FROM social_channels c JOIN social_accounts a ON a.id=c.social_account_id WHERE c.id=? AND c.provider_id='linkedin'");$stmt->execute([$channelId]);$channel=$stmt->fetch();if(!$channel)fail('LINKEDIN_CHANNEL_NOT_FOUND','LinkedIn-Zielkanal nicht gefunden.',404);if($channel['channel_type']!=='personal')fail('LINKEDIN_PERSONAL_ONLY','Echte Testbeiträge sind derzeit nur für persönliche LinkedIn-Profile erlaubt.',422);if($channel['status']!=='active'||$channel['account_status']!=='connected')fail('LINKEDIN_NOT_CONNECTED','Das persönliche LinkedIn-Profil ist nicht verbunden.',422);if(!in_array('w_member_social',linkedInScopeList($channel['scopes']),true)||(int)$channel['can_publish']!==1)fail('LINKEDIN_MEMBER_SCOPE','Für echte LinkedIn-Beiträge fehlt die Berechtigung w_member_social.',422);if(is_string($channel['token_expires_at'])&&strtotime($channel['token_expires_at'])<=time())fail('LINKEDIN_POST_TOKEN','Die LinkedIn-Verbindung ist abgelaufen. Bitte erneut verbinden.',422);try{$accessToken=decryptSecret((string)$channel['access_token_encrypted']);$payload=['author'=>'urn:li:person:'.$channel['external_account_id'],'commentary'=>$text,'visibility'=>$visibility,'distribution'=>['feedDistribution'=>'MAIN_FEED','targetEntities'=>[],'thirdPartyDistributionChannels'=>[]],'lifecycleState'=>'PUBLISHED','isReshareDisabledByAuthor'=>false];$postId=linkedInPostRequest($accessToken,$payload);recordLinkedInPublishingAttempt($channelId,$text,$visibility,'success',$postId,null);ok(['status'=>'success','message'=>'LinkedIn-Beitrag erfolgreich veröffentlicht.','postId'=>$postId,'publishedAt'=>date(DATE_ATOM),'channelId'=>$channelId]);}catch(OAuthException $exception){recordLinkedInPublishingAttempt($channelId,$text,$visibility,'failed',null,$exception->errorCode);throw $exception;}catch(CryptoException){recordLinkedInPublishingAttempt($channelId,$text,$visibility,'failed',null,'LINKEDIN_POST_TOKEN');throw new OAuthException('LINKEDIN_POST_TOKEN','Die LinkedIn-Verbindung ist ungültig. Bitte erneut verbinden.',422);}}
